#!/usr/bin/env bash

# SIGN KERNEL IMAGE AND ANY ASSOCIATED UNIFIED KERNEL IMAGE WITH ALL KEYS UNDER THE SPECIFIED SYSTEM-WIDE PATH.

KEYCHAIN_PATH="/usr/share/secureboot/keychain"

[ ! -d "$KEYCHAIN_PATH" ] && printf "KEYCHAIN DIRECTORY NOT FOUND: %s\n" "$KEYCHAIN_PATH" && exit 1

PRESET_KERNEL="${MKINITCPIO_PROCESS_PRESET%-*}"   # EVERYTHING EXCEPT THE LAST '-'
PRESET_NAME="${MKINITCPIO_PROCESS_PRESET##*-}"    # EVERYTHING AFTER THE LAST '-'

function OPTION() {
  grep -Po "^(${PRESET_NAME}|ALL)_${1}=(\K.*)$" "/etc/mkinitcpio.d/${PRESET_KERNEL}.preset"  | tr -d '"'
}

OPTION_KERNEL_VERSION="kver"
OPTION_UNIFIED_KERNEL_IMAGE="uki"

KERNEL_VERSION_PATH="$(OPTION "$OPTION_KERNEL_VERSION")"
UNIFIED_KERNEL_IMAGE_PATH="$(OPTION "$OPTION_UNIFIED_KERNEL_IMAGE")"

echo "SIGNATURE TARGETS:" "$KERNEL_VERSION_PATH" "$UNIFIED_KERNEL_IMAGE_PATH"

function SIGN_TARGET_FILE() {
  TARGET_FILE=$1
  TARGET_CERTIFICATE_FILE=$2
  TARGET_PRIVATE_KEY_FILE=$3

  if ! sbverify --cert "$TARGET_CERTIFICATE_FILE" "$TARGET_FILE" >/dev/null 2>&1; then
    echo "SIGNING $TARGET_FILE WITH $TARGET_CERTIFICATE_FILE"
    sbsign --key "$TARGET_PRIVATE_KEY_FILE" --cert "$TARGET_CERTIFICATE_FILE" --output "$TARGET_FILE" "$TARGET_FILE"
  else
    echo "$TARGET_FILE ALREADY SIGNED WITH $TARGET_CERTIFICATE_FILE"
  fi
}

for BASE_FILENAME in $(for FILE_PATH in "$KEYCHAIN_PATH"/*.{cer,crt,key}; do [ -f "$FILE_PATH" ] && basename "$FILE_PATH" | cut -d. -f1; done | sort -u); do
  CERTIFICATE_CER_FILE="$KEYCHAIN_PATH/$BASE_FILENAME.cer"
  CERTIFICATE_CRT_FILE="$KEYCHAIN_PATH/$BASE_FILENAME.crt"
  PRIVATE_KEY_FILE="$KEYCHAIN_PATH/$BASE_FILENAME.key"

  # REQUIRE ALL THREE FILES TO BE PRESENT
  if [[ -f "$CERTIFICATE_CER_FILE" && -f "$CERTIFICATE_CRT_FILE" && -f "$PRIVATE_KEY_FILE" ]]; then
    echo "PROCESSING KEYCHAIN: $BASE_FILENAME"
    SIGN_TARGET_FILE "$KERNEL_VERSION_PATH" "$CERTIFICATE_CRT_FILE" "$PRIVATE_KEY_FILE"
    SIGN_TARGET_FILE "$UNIFIED_KERNEL_IMAGE_PATH"  "$CERTIFICATE_CRT_FILE" "$PRIVATE_KEY_FILE"
  else
    echo "SKIPPING $BASE_FILENAME (MISSING ONE OF CERTIFICATE .CER, CERTIFICATE .CRT, PRIVATE KEY .KEY)"
  fi
done
